// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dptts2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 12', function test( t ) {
	t.strictEqual( dptts2.length, 12, 'returns expected value' );
	t.end();
});

tape( 'the function returns the input array unchanged if `N` is zero', function test( t ) {
	var expected;
	var out;
	var B;

	B = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	expected = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );

	out = dptts2( 0, 2, new Float64Array( [] ), 1, 0, new Float64Array( [] ), 1, 0, B, 1, 2, 0 ); // eslint-disable-line max-len
	t.strictEqual( out, B, 'returns a reference to `B`' );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function returns the input array unchanged if `nrhs` is zero', function test( t ) {
	var expected;
	var data;
	var out;
	var B;

	data = COL_MAJOR_NRHS_GT_ONE;

	B = new Float64Array( data.B );
	expected = new Float64Array( data.B );

	out = dptts2( data.N, 0, new Float64Array( data.D ), data.sd, data.od, new Float64Array( data.E ), data.se, data.oe, B, data.sb1, data.sb2, data.ob ); // eslint-disable-line max-len
	t.strictEqual( out, B, 'returns a reference to `B`' );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function does not mutate the input arrays `D` and `E`', function test( t ) {
	var data;
	var D;
	var E;
	var i;

	data = [ COL_MAJOR_NRHS_GT_ONE, ROW_MAJOR_NRHS_GT_ONE, COL_MAJOR_N_EQ_ONE, NEG_STRIDE_COL_MAJOR_NRHS_GT_ONE, COMPLEX_ACCESS_ROW_MAJOR_NRHS_GT_ONE ]; // eslint-disable-line max-len

	for ( i = 0; i < data.length; i++ ) {
		D = new Float64Array( data[ i ].D );
		E = new Float64Array( data[ i ].E );
		dptts2( data[ i ].N, data[ i ].nrhs, D, data[ i ].sd, data[ i ].od, E, data[ i ].se, data[ i ].oe, new Float64Array( data[ i ].B ), data[ i ].sb1, data[ i ].sb2, data[ i ].ob ); // eslint-disable-line max-len
		t.deepEqual( D, new Float64Array( data[ i ].D ), 'returns expected value' );
		t.deepEqual( E, new Float64Array( data[ i ].E ), 'returns expected value' );
	}
	t.end();
});

